 "content": "def transform(grid):
    # The 1-filled rectangle is the picture; the three isolated colored cells
    # outside it specify where its three colored corner markers should end up.
    h0, w0 = len(grid), len(grid[0])
    ones = [(r, c) for r in range(h0) for c in range(w0) if grid[r][c] == 1]
    r0, r1 = min(r for r, c in ones), max(r for r, c in ones)
    c0, c1 = min(c for r, c in ones), max(c for r, c in ones)
    panel = [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]
    h, w = len(panel), len(panel[0])

    outside = [(r, c, grid[r][c]) for r in range(h0) for c in range(w0)
               if grid[r][c] not in (0, 1)
               and not (r0 <= r <= r1 and c0 <= c <= c1)]
    if len(outside) != 3:
        return panel
    er0, er1 = min(r for r, c, v in outside), max(r for r, c, v in outside)
    ec0, ec1 = min(c for r, c, v in outside), max(c for r, c, v in outside)

    def corner(r, c, top, bottom, left, right):
        return ('T' if abs(r - top) <= abs(r - bottom) else 'B') + \
               ('L' if abs(c - left) <= abs(c - right) else 'R')

    target = {v: corner(r, c, er0, er1, ec0, ec1) for r, c, v in outside}
    colors = set(target)
    marks = {}
    for r in range(h):
        for c in range(w):
            if panel[r][c] in colors:
                marks.setdefault(panel[r][c], (r, c))

    # Each mapping returns transformed coordinates plus the resulting size.
    transforms = [
        (lambda r, c: (r, c), h, w),
        (lambda r, c: (h - 1 - r, w - 1 - c), h, w),
        (lambda r, c: (h - 1 - r, c), h, w),
        (lambda r, c: (r, w - 1 - c), h, w),
        (lambda r, c: (c, r), w, h),
        (lambda r, c: (w - 1 - c, h - 1 - r), w, h),
        (lambda r, c: (c, h - 1 - r), w, h),
        (lambda r, c: (w - 1 - c, r), w, h),
    ]

    for coord, oh, ow in transforms:
        if any(v not in marks for v in colors):
            continue
        ok = True
        for v in colors:
            rr, cc = coord(*marks[v])
            got = corner(rr, cc, 1, oh - 2, 1, ow - 2)
            if got != target[v]:
                ok = False
                break
        if ok:
            out = [[0] * ow for _ in range(oh)]
            for r in range(h):
                for c in range(w):
                    rr, cc = coord(r, c)
                    out[rr][cc] = panel[r][c]
            return out

    return panel
